  c.contactados = c.enviado + c.sin_respuesta + c.respondio + c.demo + c.cerrado;
  c.respuestas = c.respondio + c.demo + c.cerrado;
  c.tasa = c.contactados ? Math.round(100 * c.respuestas / c.contactados) : 0;
  c.facturado = 0;
  c.mrr = 0;
